#include <stdio.h>
#include <math.h>
/* ex02：香农定理——有噪声信道的极限速率
 * C = W·log2(1 + S/N)，S/N 是功率比（无量纲）。
 * 题目通常给 dB：S/N(dB) = 10·log10(S/N)  ->  S/N = 10^(dB/10)
 * 换算这一步是 408 的高频失分点。*/
int main(void) {
    double W = 3000.0;                 /* 3kHz 带宽 */
    double dbs[] = {10.0, 20.0, 30.0, 40.0};

    printf("香农：C = W·log2(1 + S/N)，W = %.0f Hz\n", W);
    printf("------------------------------------------------------\n");
    printf("%-12s %-14s %-16s %s\n", "信噪比(dB)", "S/N(倍)", "极限速率 C", "说明");
    for (int i = 0; i < 4; i++) {
        double snr = pow(10.0, dbs[i] / 10.0);      /* dB -> 倍数 */
        double C = W * log2(1.0 + snr);
        printf("%-12.0f %-14.0f %-16.0f %s\n", dbs[i], snr, C,
               dbs[i] == 30.0 ? "电话线典型值" : dbs[i] == 40.0 ? "优质线路" : "");
    }
    printf("------------------------------------------------------\n");
    printf("要点1：dB 是「对数刻度」，30dB 不是 30 倍，而是 1000 倍。\n");
    printf("要点2：香农给的是「上限」，实际速率还要受奈氏约束，取两者较小值。\n");
    printf("要点3：想提高速率只有两条路 —— 加带宽 W，或提高信噪比 S/N。\n");
    return 0;
}
